package com.wayrapass.controller; import com.wayrapass.dto.request.CatalogRequests;import com.wayrapass.dto.response.CatalogResponses;import com.wayrapass.service.CatalogService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/vehicles") @RequiredArgsConstructor @PreAuthorize("hasRole('COORDINATOR')") public class VehicleController{private final CatalogService s;@GetMapping public List<CatalogResponses.Vehicle> all(){return s.vehicles();}@GetMapping("/{id}") public CatalogResponses.Vehicle one(@PathVariable Long id){return s.vehicle(id);}@PostMapping @ResponseStatus(HttpStatus.CREATED) public CatalogResponses.Vehicle create(@Valid @RequestBody CatalogRequests.Vehicle r){return s.saveVehicle(null,r);}@PutMapping("/{id}") public CatalogResponses.Vehicle update(@PathVariable Long id,@Valid @RequestBody CatalogRequests.Vehicle r){return s.saveVehicle(id,r);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){s.deleteVehicle(id);}}
